"use client";

import { useState } from "react";

export default function Home() {
  const [topic, setTopic] = useState("");
  const [language, setLanguage] = useState("Deutsch");
  const [platform, setPlatform] = useState("TikTok");
  const [category, setCategory] = useState("Business");

  const [hooks, setHooks] = useState<string[]>([]);
  const [savedHooks, setSavedHooks] = useState<string[]>([]);
  const [copied, setCopied] = useState("");

  const generateHooks = () => {
    if (!topic) {
      alert("Bitte Thema eingeben");
      return;
    }

    let fakeHooks: string[] = [];

    switch (category) {
      case "Fitness":
        fakeHooks = [
          `Dieser ${topic}-Workout verändert alles.`,
          `Niemand trainiert ${topic} richtig.`,
          `Die Wahrheit über ${topic} Fitness.`,
          `Warum dein ${topic} Training nicht funktioniert.`,
          `${topic} Tipps, die viral gehen.`,
        ];
        break;

      case "Beauty":
        fakeHooks = [
          `Dieser ${topic}-Beauty-Hack geht viral.`,
          `Die Wahrheit über ${topic} Skincare.`,
          `Warum dein ${topic} Make-up nicht hält.`,
          `${topic} Tipps, die jeder kennen sollte.`,
          `Niemand spricht über ${topic} so.`,
        ];
        break;

      case "Gaming":
        fakeHooks = [
          `Dieser ${topic}-Move ist unfair.`,
          `Niemand kennt diesen ${topic} Trick.`,
          `Warum Pros ${topic} anders spielen.`,
          `${topic} Tipps für Anfänger.`,
          `Dieser ${topic} Fehler kostet dich Wins.`,
        ];
        break;

      default:
        fakeHooks = [
          `Niemand spricht über ${topic} so...`,
          `Dieser ${topic}-Trick verändert alles.`,
          `Du machst ${topic} wahrscheinlich falsch.`,
          `Das musst du über ${topic} wissen.`,
          `Die Wahrheit über ${topic}, die kaum jemand sagt.`,
        ];
    }

    setHooks(fakeHooks);
  };

  const copyHook = async (hook: string) => {
    await navigator.clipboard.writeText(hook);

    setCopied(hook);

    setTimeout(() => {
      setCopied("");
    }, 2000);
  };

  const saveHook = (hook: string) => {
    if (!savedHooks.includes(hook)) {
      setSavedHooks([...savedHooks, hook]);
    }
  };

  const downloadHooks = () => {
    const text = savedHooks.join("\n\n");

    const blob = new Blob([text], {
      type: "text/plain",
    });

    const url = URL.createObjectURL(blob);

    const a = document.createElement("a");

    a.href = url;
    a.download = "saved-hooks.txt";

    a.click();

    URL.revokeObjectURL(url);
  };

  return (
    <main className="min-h-screen bg-gradient-to-br from-black via-zinc-900 to-black text-white p-6 flex items-center justify-center">
      <div className="w-full max-w-2xl">

        <div className="text-center mb-10">
          <h1 className="text-6xl font-bold mb-4 bg-gradient-to-r from-white to-gray-500 bg-clip-text text-transparent">
            Viral Hook AI
          </h1>

          <p className="text-gray-400 text-lg">
            Generate viral hooks for {platform}
          </p>
        </div>

        <div className="bg-zinc-900 border border-zinc-800 rounded-3xl p-6 shadow-2xl">

          <select
            value={platform}
            onChange={(e) => setPlatform(e.target.value)}
            className="w-full rounded-2xl p-4 mb-4 bg-black border border-zinc-700"
          >
            <option>TikTok</option>
            <option>Instagram</option>
            <option>YouTube</option>
          </select>

          <select
            value={language}
            onChange={(e) => setLanguage(e.target.value)}
            className="w-full rounded-2xl p-4 mb-4 bg-black border border-zinc-700"
          >
            <option>Deutsch</option>
            <option>English</option>
            <option>Türkçe</option>
          </select>

          <select
            value={category}
            onChange={(e) => setCategory(e.target.value)}
            className="w-full rounded-2xl p-4 mb-4 bg-black border border-zinc-700"
          >
            <option>Business</option>
            <option>Fitness</option>
            <option>Beauty</option>
            <option>Gaming</option>
          </select>

          <input
            value={topic}
            onChange={(e) => setTopic(e.target.value)}
            placeholder="Enter your topic..."
            className="w-full rounded-2xl p-4 mb-4 bg-black border border-zinc-700"
          />

          <button
            onClick={generateHooks}
            className="w-full bg-white text-black py-4 rounded-2xl font-bold text-lg hover:scale-[1.02] transition"
          >
            Generate Hooks
          </button>
        </div>

        <div className="mt-8 space-y-5">
          {hooks.map((hook, index) => (
            <div
              key={index}
              className="bg-zinc-900 border border-zinc-800 rounded-3xl p-5 shadow-xl"
            >
              <p className="text-lg mb-4">{hook}</p>

              <div className="flex gap-3">
                <button
                  onClick={() => copyHook(hook)}
                  className="bg-white text-black px-5 py-2 rounded-xl font-semibold hover:scale-105 transition"
                >
                  {copied === hook ? "Copied!" : "Copy"}
                </button>

                <button
                  onClick={() => saveHook(hook)}
                  className="bg-pink-500 px-5 py-2 rounded-xl font-semibold hover:scale-105 transition"
                >
                  ❤️ Save
                </button>
              </div>
            </div>
          ))}
        </div>

        {savedHooks.length > 0 && (
          <div className="mt-12">
            <h2 className="text-3xl font-bold mb-6">
              Saved Hooks ❤️
            </h2>

            <button
              onClick={downloadHooks}
              className="mb-6 bg-white text-black px-5 py-2 rounded-xl font-semibold"
            >
              Download TXT
            </button>

            <div className="space-y-4">
              {savedHooks.map((hook, index) => (
                <div
                  key={index}
                  className="bg-zinc-800 rounded-2xl p-4"
                >
                  {hook}
                </div>
              ))}
            </div>
          </div>
        )}
      </div>
    </main>
  );
}